/projects/{projectId}/servers {"operationId":"createProjectServer","tags":["Servers"],"summary":"Save a server into a project","description":"Creates a saved MCP server and responds `201` with its detail. This is the provisioning entry point: every eval, host and environment route addresses servers that were created here. Names are unique per workspace, so a clash responds `409` rather than silently returning the existing row. Secret-bearing fields (`env`, `headers`, `clientSecret`) are encrypted at rest and never returned by any read.","parameters":[{"$ref":"#/components/parameters/projectId"}],"requestBody":{"required":true,"content":{"application/json":{"schema":{"$ref":"#/components/schemas/ProjectServerCreateRequest"},"example":{"name":"learn","enabled":true,"transportType":"http","url":"https://learn.mcpjam.com/mcp"}}}},"responses":{"201":{"description":"The server was created.","content":{"application/json":{"schema":{"$ref":"#/components/schemas/ProjectServer"}}}},"400":{"$ref":"#/components/responses/ValidationError"},"401":{"$ref":"#/components/responses/Unauthorized"},"403":{"$ref":"#/components/responses/Forbidden"},"404":{"$ref":"#/components/responses/NotFound"},"409":{"$ref":"#/components/responses/Conflict"},"429":{"$ref":"#/components/responses/RateLimited"},"500":{"$ref":"#/components/responses/InternalError"},"502":{"$ref":"#/components/responses/ServerUnreachable"}}}
/projects/{projectId}/eval-suites/from-file {"operationId":"syncFileOwnedEvalSuite","tags":["Eval runs"],"summary":"Resolve or create a file-owned eval suite","description":"Resolve a file-owned suite by declared id within the project, or create one. Lookup is by `(projectId, declaredSuiteId)` and never by name. A UI-authored suite has no declared id and cannot be claimed. The inspector parses the suite file; this body is the declared identity, source hash, optional provenance, and hosted settings — not the raw file.\n\n`201` on first create; `200` on a later update of the same declared id.","parameters":[{"$ref":"#/components/parameters/evalVocabularyHeader"},{"$ref":"#/components/parameters/projectId"}],"requestBody":{"required":true,"content":{"application/json":{"schema":{"$ref":"#/components/schemas/EvalSuiteFromFileRequest"}}}},"responses":{"200":{"description":"The existing file-owned suite was updated.","content":{"application/json":{"schema":{"$ref":"#/components/schemas/EvalSuiteFromFileSynced"}}}},"201":{"description":"A new file-owned suite was created.","content":{"application/json":{"schema":{"$ref":"#/components/schemas/EvalSuiteFromFileSynced"}}}},"400":{"$ref":"#/components/responses/ValidationError"},"401":{"$ref":"#/components/responses/Unauthorized"},"403":{"$ref":"#/components/responses/Forbidden"},"404":{"$ref":"#/components/responses/NotFound"},"409":{"$ref":"#/components/responses/Conflict"},"429":{"$ref":"#/components/responses/RateLimited"},"500":{"$ref":"#/components/responses/InternalError"},"502":{"$ref":"#/components/responses/ServerUnreachable"}}}
/projects/{projectId}/eval-suites/{suiteId}/cases {"operationId":"createEvalCase","x-mcpjam-eval-vocabulary":{"2":{"requestBody":"EvalCaseCreateRequestV2","response":"EvalCaseV2"}},"tags":["Eval runs"],"summary":"Create an eval case","description":"Adds one case to the suite. Both `title` and a non-empty `steps` array are required — `steps` is optional on the shared case shape so PATCH can be partial, but a case persisted without executable steps could never run. When `models` is omitted the suite's configured model is used.","parameters":[{"$ref":"#/components/parameters/evalVocabularyHeader"},{"$ref":"#/components/parameters/projectId"},{"$ref":"#/components/parameters/suiteId"},{"$ref":"#/components/parameters/declaredSuiteIdQuery"}],"requestBody":{"required":true,"content":{"application/json":{"schema":{"$ref":"#/components/schemas/EvalCaseCreateRequest"},"example":{"title":"lists files","steps":[{"id":"s1","kind":"prompt","prompt":"List the files in the project root."},{"id":"s2","kind":"assert","assertion":{"type":"toolCalledWith","toolName":"list_files","args":{"args":{}}}}]}}}},"responses":{"201":{"description":"The created case.","content":{"application/json":{"schema":{"$ref":"#/components/schemas/EvalCase"}}}},"400":{"$ref":"#/components/responses/ValidationError"},"401":{"$ref":"#/components/responses/Unauthorized"},"403":{"$ref":"#/components/responses/Forbidden"},"404":{"$ref":"#/components/responses/NotFound"},"409":{"$ref":"#/components/responses/Conflict"},"429":{"$ref":"#/components/responses/RateLimited"},"500":{"$ref":"#/components/responses/InternalError"},"502":{"$ref":"#/components/responses/ServerUnreachable"}}}
